package com.servicerca.model;import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="request_status_history") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class RequestStatusHistory{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(optional=false)@JoinColumn(name="request_id")private ServiceRequest request;@Enumerated(EnumType.STRING)@Column(nullable=false)private RequestStatus status;@ManyToOne@JoinColumn(name="actor_id")private User actor;@Column(name="created_at",nullable=false)private Instant createdAt;@PrePersist void pre(){if(createdAt==null)createdAt=Instant.now();}}
